        List<QueueMissing> missing=new ArrayList<>();List<PendingOccurrence> observed=pending==null?List.of():observed(pending,true);if(pending==null)missing.add(new QueueInput("monthly_daily_queue_inputs_v1.manager_army_id_list_2a5a8"));
