        if(prefix)for(int i=0;i<loss.requests().size();i++){var r=loss.requests().get(i);if(r.rawFullId()==null||r.rawFullId()<0||r.rawFullId()>0xffffffffL){prefix=false;appended.clear();break;}appended.add(new PendingOccurrence(pending==null?null:pending.size()+i,r.rawFullId().intValue(),r.rawFullId(),"conditional_daily_assault_original_raw_ArmyID_append",null,i,r.groupIndex(),r.armyIndex(),true));}
