            boolean ready=vectors.size()==2&&vectors.stream().allMatch(VectorRelease::ready);records.add(new ReleasedRecord(g.nativeIndex(),slot,ready,vectors));if(!ready)break;int after=remaining-1;stores.add(new ControlStore(slot,b,remaining,after));controls.put(slot,new Control(slot,0,c==null?null:c.unavailableReason()));untouched.remove(Long.valueOf(slot));remaining=after;slot++;
